int nextState(int s, int d) {
    if (s == 4) return 4;
    if (s == 0) return d == 5 ? 1 : 0;
    if (s == 1) return d == 1 ? 2 : (d == 5 ? 1 : 0);
    if (s == 2) return 3;
    if (s == 3) return d == 3 ? 4 : (d == 5 ? 1 : 0);
    return 0;
