long long dp(int pos, int state, int tight, int started) {
    if (pos == n) {
        return (started && state == 4) ? 1 : 0;
    }
    auto key = make_tuple(pos, state, tight, started);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    int limit = tight ? (N[pos] - '0') : 9;
    long long res = 0;
    for (int d = 0; d <= limit; d++) {
        int newTight = tight && (d == limit);
        int newStarted = started || (d != 0);
        int newState = state;
        if (newStarted) {
            newState = nextState(state, d);
        }
        res += dp(pos + 1, newState, newTight, newStarted);
    }
    memo[key] = res;
    return res;
